document.addEventListener('DOMContentLoaded', function() {
  const containerCounts = document.createElement('div');
  containerCounts.id = 'organisms-table-container';
  containerCounts.style.marginBottom = '50px';
  document.body.appendChild(containerCounts);

  const titleCounts = document.createElement('h2');
  titleCounts.textContent = 'Organism Counts Table';
  containerCounts.appendChild(titleCounts);

  const downloadBtnCounts = document.createElement('button');
  downloadBtnCounts.textContent = 'Download Table Data';
  downloadBtnCounts.style.marginBottom = '10px';
  downloadBtnCounts.onclick = function() {
    organismsTableCounts.download('csv', 'organism_counts.csv');
  };
  containerCounts.appendChild(downloadBtnCounts);

  const tableDivCounts = document.createElement('div');
  tableDivCounts.id = 'organisms-table';
  containerCounts.appendChild(tableDivCounts);

  const organismsTableCounts = new Tabulator('#organisms-table', {
    data: organismsDataCounts,
    layout: 'fitColumns',
    pagination: 'local',
    paginationSize: 20,
    initialSort: [ { column:'count', dir:'desc' } ],
    columns: [
      { title: 'Organism', field: 'organism', sorter: 'string', headerFilter: 'input', formatter:'html' },
      { title: 'Synonyms', field: 'synonyms', sorter: 'string', headerFilter: 'input' },
      { title: 'Kingdom', field: 'kingdom', sorter: 'string', headerFilter: 'input' },
      { title: 'Phylum', field: 'phylum', sorter: 'string', headerFilter: 'input' },
      { title: 'Count', field: 'count', sorter: 'number', headerFilter: 'input' },
      { title: 'Count More than 2', field: 'count_2', sorter: 'number', headerFilter: 'input' },
    ]
  });
}); // end DOMContentLoaded
